import { writeFile, mkdir } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const base = (process.env.SITE_URL || 'https://jo3lbenjamin.github.io/cs2024-final-project/').replace(/\/?$/, '/');
const sunURL = 'https://shopee.sg/-BEST-SKIN1004-Madagascar-Centella-Hyalu-cica-Water-Fit-Sun-Serum-SPF50-PA-No-White-Cast-Long-lasting-Hydrating-Lightweight-for-Daily-Use-50ml-i.322645596.19703489951';
