const arrow = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.5"/></svg>';
const external = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M7 17 17 7M7 7h10v10" stroke="currentColor" stroke-width="1.5"/></svg>';
const icon = name => ({sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4.2 4.2l2.1 2.1m11.4 11.4 2.1 2.1M4.2 19.8l2.1-2.1M17.7 6.3l2.1-2.1"/>',drop:'<path d="M12 2c-2 4-7 8-7 13a7 7 0 0 0 14 0c0-5-5-9-7-13Z"/><path d="M8 15c0 2 1 3 3 4"/>',leaf:'<path d="M20 3C9 2 3 7 4 14c1 7 11 8 14 0 1-3 1-7 2-11Z"/><path d="M3 22 15 9"/>',star:'<path d="m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6L12 2Z"/>'}[name] || '');
const svg = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.2" aria-hidden="true">${icon(name)}</svg>`;
const img = (name, alt, cls='', eager=false) => `<img src="assets/images/${name}.webp" alt="${alt}" width="800" height="800" class="${cls}" ${eager ? 'fetchpriority="high"' : 'loading="lazy"'} decoding="async">`;
const link = (url, text, cls='btn btn-primary') => `<a class="${cls}" href="${url}" target="_blank" rel="noopener noreferrer">${text}${external}<span class="sr-only"> (opens Shopee in a new tab)</span></a>`;
const btn = (url,text,cls='btn btn-primary') => `<a class="${cls}" href="${url}">${text}${arrow}</a>`;
const eyebrow = text => `<p class="eyebrow"><span></span>${text}</p>`;
const crumbs = name => `<nav class="breadcrumbs wrap" aria-label="Breadcrumb"><a href="index.html">Home</a><span aria-hidden="true">/</span><span>${name}</span></nav>`;
const faqs = entries => `<div class="accordions">${entries.map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">+</span></summary><div class="answer">${a}</div></details>`).join('')}</div>`;
const productCard = (kind) => kind==='sun' ? `<article class="product-card"><a class="card-visual blue" href="sun-serum.html" aria-label="The daily essential — explore Daily Sun Serum">${img('aureveil-sun-serum','Aureveil Daily Sun Serum, white tube with pale blue cap','cutout')}<img class="card-alternate" src="assets/images/aureveil-sun-campaign.webp" srcset="assets/images/aureveil-sun-campaign-480.webp 480w, assets/images/aureveil-sun-campaign.webp 960w" sizes="(max-width: 650px) calc(100vw - 40px), 45vw" alt="" width="960" height="1200" loading="lazy" decoding="async" aria-hidden="true"><span class="visual-tag">The daily essential</span></a><div class="card-body"><p class="micro">AUREVEIL · 50ml · SPF50+ PA++++</p><h3><a href="sun-serum.html">Daily Sun Serum</a></h3><p>Lightweight protection. A fresh, dewy finish.</p><div class="card-bottom"><span><small>Price</small>S$39.90</span><a class="text-link" href="sun-serum.html">Meet your SPF ${arrow}</a></div></div></article>` : `<article class="product-card"><a class="card-visual pearl" href="cloudy-mist.html" aria-label="The little reset — explore Cloud Mist">${img('aureveil-cloudy-mist','Aureveil Cloud Mist, pale blue bottle with clear cap','cutout')}<img class="card-alternate" src="assets/images/aureveil-mist-campaign.webp" srcset="assets/images/aureveil-mist-campaign-480.webp 480w, assets/images/aureveil-mist-campaign.webp 960w" sizes="(max-width: 650px) calc(100vw - 40px), 45vw" alt="" width="960" height="1200" loading="lazy" decoding="async" aria-hidden="true"><span class="visual-tag">The little reset</span></a><div class="card-body"><p class="micro">AUREVEIL · 120ml · Facial mist</p><h3><a href="cloudy-mist.html">Cloud Mist</a></h3><p>A fine cloud of hydration. A moment for you.</p><div class="card-bottom"><span><small>Price</small>S$59.90</span><a class="text-link" href="cloudy-mist.html">Find your refresh ${arrow}</a></div></div></article>`;
const routineCTA = () => `<section class="routine-cta"><div class="wrap cta-inner"><div>${eyebrow('A moment, just for you')}<h2>Find a ritual that<br><em>fits your day.</em></h2></div><div><p>A few simple questions. A thoughtful place to start.</p>${btn('routine.html','Find my daily ritual','btn btn-light')}</div></div></section>`;
const duoPreview = () => `<section class="duo-feature section"><div class="wrap duo-layout"><div class="duo-art"><div class="duo-circle"></div>${img('aureveil-sun-serum','Daily Sun Serum 50ml','duo-sun')}${img('aureveil-cloudy-mist','Cloud Mist 120ml','duo-mist')}<span class="seal"><span class="seal-kicker">TWO LITTLE</span><i>daily<br>rituals</i></span></div><div class="duo-copy">${eyebrow('Better as a ritual')}<h2>Protect.<br>Refresh.<br><em>Go gently.</em></h2><p>Daily sun protection meets a fresh cloud of hydration. Two complementary essentials, thoughtfully paired for your full, beautifully busy life.</p><div class="bundle-price"><span>S$84.90</span><div><small>Duo price</small><p>Individual total S$99.80</p></div></div>${btn('duo.html','Discover the duo')}</div></div></section>`;

const pages = [
{file:'index.html',nav:'home',title:'Aureveil | Daily Sun Protection & Thoughtful Skincare',description:'Discover Aureveil’s daily skincare edit. Explore lightweight sun protection, refreshing hydration and thoughtful rituals for long days and full lives.',content:()=>`
<section class="hero wrap"><div class="hero-copy">${eyebrow('Daily care. Quietly extraordinary.')}<h1>Care for today.<br>Glow into<br><em>tomorrow.</em></h1><p class="hero-intro">Daily protection. A moment of calm.<br>Thoughtful skincare for the life you live.</p><div class="hero-actions">${btn('sun-serum.html','Discover the Sun Serum')}<a class="text-link" href="duo.html">Meet the duo ${arrow}</a></div><p class="hero-product-note">DAILY SUN SERUM <span>SPF50+ PA++++ · 50ml</span></p></div><figure class="hero-art"><img src="assets/images/aureveil-sun-campaign.webp" srcset="assets/images/aureveil-sun-campaign-480.webp 480w, assets/images/aureveil-sun-campaign.webp 960w" sizes="(max-width: 650px) calc(100vw - 40px), 45vw" alt="Aureveil Daily Sun Serum on ivory stone beside pale-blue glass in morning light" width="960" height="1200" class="hero-photo" fetchpriority="high" decoding="async"><figcaption>THE DAILY ESSENTIAL <span>01 / AUREVEIL</span></figcaption></figure></section>
<div class="benefit-strip"><div class="wrap"><span>${svg('sun')}Daily UV protection</span><span>${svg('drop')}Hydration, without the heaviness</span><span>${svg('leaf')}A ritual worth keeping</span></div></div>
<section class="section wrap"><div class="section-heading"><div>${eyebrow('The daily edit')}<h2>One essential.<br><em>One small reset.</em></h2></div><p>Skincare doesn’t have to ask more of your day.<br>Meet two essentials that make room for you.</p></div><div class="product-grid">${productCard('sun')}${productCard('mist')}</div></section>
<section class="editorial wrap"><div class="editorial-image"><img src="assets/images/lifestyle.webp" alt="Editorial portrait of a woman in her early thirties enjoying a quiet morning by a window" width="1200" height="800" loading="lazy" decoding="async"><span class="image-caption">A LITTLE CARE, ON YOUR OWN TERMS.</span></div><div class="editorial-copy">${eyebrow('For the life you are living')}<h2>Your years are yours.<br><em>So is your glow.</em></h2><p>Early meetings. Late trains. Air-conditioned afternoons. A calendar that somehow fills itself.</p><p>Aureveil is a considered skincare edit for your late twenties and early thirties: daily protection and comfortable hydration, without turning your routine into another to-do list.</p><a class="text-link" href="about.html">Our approach to everyday care ${arrow}</a></div></section>
${duoPreview()}
<section class="section wrap"><div class="section-heading"><div>${eyebrow('Care, made clearer')}<h2>A little knowledge.<br><em>A better daily ritual.</em></h2></div><a class="text-link" href="journal.html">Read the journal ${arrow}</a></div><div class="journal-grid"><a href="journal.html#sun-protection" class="journal-card"><div class="journal-image">${img('aureveil-sun-detail','Aureveil Daily Sun Serum in a product flatlay')}</div><p class="micro">THE EVERYDAY ESSENTIAL · 3 MIN READ</p><h3>Why your daily SPF deserves a permanent place.</h3><span class="text-link">Read the guide ${arrow}</span></a><a href="journal.html#hydration" class="journal-card"><div class="journal-image">${img('aureveil-mist-detail','Cloud Mist in a softly lit blue product composition')}</div><p class="micro">THE LITTLE RESET · 2 MIN READ</p><h3>Hydration for the space between meetings.</h3><span class="text-link">Read the guide ${arrow}</span></a></div></section>
${routineCTA()}`},
{file:'sun-serum.html',nav:'shop',title:'Daily Sun Serum SPF50+ PA++++ 50ml | Aureveil',description:'Explore Aureveil Daily Sun Serum SPF50+ PA++++ 50ml: lightweight hydration, daily sun protection and a dewy finish. Discover your daily essential.',content:()=>`${crumbs('Daily Sun Serum')}
<section class="product-hero wrap"><div class="product-gallery"><div class="gallery-main blue">${img('aureveil-sun-serum','Front view of the Aureveil Daily Sun Serum','cutout',true)}</div><div class="gallery-thumbs" aria-label="Daily Sun Serum image selection"><button class="thumb active" data-gallery="aureveil-sun-serum" aria-pressed="true" aria-label="Show Daily Sun Serum packshot">${img('aureveil-sun-serum','Daily Sun Serum packshot thumbnail')}</button><button class="thumb" data-gallery="aureveil-sun-campaign" aria-pressed="false" aria-label="Show Daily Sun Serum campaign photograph">${img('aureveil-sun-campaign','Daily Sun Serum campaign thumbnail')}</button><button class="thumb" data-gallery="aureveil-sun-detail" aria-pressed="false" aria-label="Show Daily Sun Serum flatlay">${img('aureveil-sun-detail','Daily Sun Serum flatlay thumbnail')}</button></div></div><div class="product-intro">${eyebrow('Your daily essential')}<p class="micro">AUREVEIL · 50ml</p><h1>Daily protection.<br><em>Beautifully light.</em></h1><p class="product-name">Daily Sun Serum<br>SPF50+ PA++++</p><p>A serum-like sunscreen that brings lightweight hydration, a dewy finish and UVA/UVB protection into your daily routine.</p><div class="pill-row"><span>SPF50+ PA++++</span><span>Dewy finish</span><span>Lightweight feel</span></div><div class="price"><span>S$39.90</span><small>Retail price · 50ml</small></div>${link(sunURL,'View Daily Sun Serum on Shopee')}<a class="upgrade-link" href="duo.html">${svg('star')}Complete the ritual with Cloud Mist ${arrow}</a></div></section>
<section class="benefit-strip"><div class="wrap"><span>${svg('sun')}UVA + UVB protection</span><span>${svg('drop')}Moisturizing serum texture</span><span>${svg('leaf')}Centella + hyaluronic acid</span></div></section>
<section class="section wrap split-copy"><div>${eyebrow('The feel-good essential')}<h2>Protection that feels<br><em>like skincare.</em></h2></div><div><p class="lead">The daily step you can look forward to.</p><p>A lightweight, serum-like texture brings hydration and a fresh, dewy finish to your daily protection step. Discover the roles of Centella asiatica, hyaluronic acid and UV filters in our ingredient guide.</p><p>For your morning commute, lunch outdoors and plans after work, make sun protection a considered part of your day.</p><a class="text-link" href="ingredients.html">Explore what is inside ${arrow}</a></div></section>
<section class="product-story section" aria-labelledby="ritual-story-heading"><div class="wrap"><div class="section-heading"><div>${eyebrow('The art of everyday care')}<h2 id="ritual-story-heading">A little intention.<br><em>Every morning.</em></h2></div><p>From the first touch<br>to the day ahead.</p></div><div class="ritual-story"><figure class="ritual-visual"><img src="assets/images/aureveil-sun-campaign.webp" srcset="assets/images/aureveil-sun-campaign-480.webp 480w, assets/images/aureveil-sun-campaign.webp 960w" sizes="(max-width: 650px) calc(100vw - 40px), 45vw" alt="Aureveil Daily Sun Serum in soft morning light" width="960" height="1200" loading="lazy" decoding="async"><figcaption><span class="story-index" aria-hidden="true">01 / 03</span> THE DAILY SUN RITUAL</figcaption><div class="story-progress" aria-hidden="true"><span></span></div></figure><div class="ritual-steps"><article class="ritual-step" data-story-step="0"><p class="micro">01 / THE TEXTURE</p><h3>A lighter<br><em>kind of essential.</em></h3><p>A serum-like texture, comfortable hydration and a fresh, dewy finish. A daily step that feels like part of your skincare.</p><a class="text-link" href="ingredients.html">Explore the ingredients ${arrow}</a></article><article class="ritual-step" data-story-step="1"><p class="micro">02 / THE MOMENT</p><h3>A quiet start.<br><em>A considered step.</em></h3><p>Apply as the last step of basic skincare, following the quantity and directions on your product label. Let it settle before makeup.</p></article><article class="ritual-step" data-story-step="2"><p class="micro">03 / THE DAY AHEAD</p><h3>Take your care<br><em>into the day.</em></h3><p>Keep sun protection in your routine. Reapply according to the label, particularly after sweating or swimming, and pair with shade and protective clothing.</p>${btn('routine.html','Find your daily ritual','btn btn-outline')}</article></div></div></div></section>
<section class="section wrap narrow">${eyebrow('A few useful answers')}<h2>Get to know <em>your SPF.</em></h2>${faqs([['What do SPF50+ and PA++++ refer to?','SPF describes protection against sunburn, primarily associated with UVB. PA is a UVA-protection rating. The Daily Sun Serum is presented with an SPF50+ PA++++ rating. Always follow the label on the item you purchase.'],['Can I wear makeup after sunscreen?','Use sunscreen as the last step of skincare, let it settle, then apply makeup gently. Follow the product label for quantity and reapplication.'],['How do I shop Daily Sun Serum?','Select View Daily Sun Serum on Shopee to open the product listing. Purchases are completed on Shopee.']])}</section>${routineCTA()}`},
{file:'cloudy-mist.html',nav:'shop',title:'Cloud Mist 120ml | Hydrate & Refresh | Aureveil',description:'Meet Aureveil Cloud Mist 120ml, an ultra-fine hydrating facial mist with a refreshing feel and dewy finish. Make room for a little daily care.',content:()=>`${crumbs('Cloud Mist')}
<section class="product-hero wrap"><div class="product-gallery"><div class="gallery-main pearl">${img('aureveil-cloudy-mist','Aureveil Cloud Mist in pale blue','cutout',true)}</div><div class="gallery-thumbs" aria-label="Cloud Mist image selection"><button class="thumb active" data-gallery="aureveil-cloudy-mist" aria-pressed="true" aria-label="Show Cloud Mist packshot">${img('aureveil-cloudy-mist','Cloud Mist packshot thumbnail')}</button><button class="thumb" data-gallery="aureveil-mist-campaign" aria-pressed="false" aria-label="Show Cloud Mist campaign photograph">${img('aureveil-mist-campaign','Cloud Mist campaign thumbnail')}</button><button class="thumb" data-gallery="aureveil-mist-detail" aria-pressed="false" aria-label="Show Cloud Mist editorial photo">${img('aureveil-mist-detail','Cloud Mist editorial thumbnail')}</button></div></div><div class="product-intro">${eyebrow('Your little reset')}<p class="micro">AUREVEIL · 120ml</p><h1>A cloud of care.<br><em>A moment for you.</em></h1><p class="product-name">Cloud Mist</p><p>An ultra-fine facial mist for a burst of hydration, a refreshing cooling feel and a dewy, glowing finish.</p><div class="pill-row"><span>Ultra-fine mist</span><span>Moisturizing</span><span>Dewy finish</span></div><div class="price"><span>S$59.90</span><small>Retail price · 120ml</small></div>${link(mistURL,'View Cloud Mist on Shopee')}<a class="upgrade-link" href="duo.html">${svg('sun')}Pair your hydration with daily sun protection ${arrow}</a></div></section>
<section class="section wrap split-copy"><div>${eyebrow('From first light to last meeting')}<h2>Room for<br><em>a little refresh.</em></h2></div><div><p class="lead">Hydration can be a moment of care.</p><p>A fine, fog-like spray offers a refreshing moment and a dewy feel. Our ingredient guide explores the moisturizing roles of green tea water, Centella and hyaluronic acid.</p><p>We suggest it as a hydration step while preparing for your day, or a small reset when skin feels dry. Follow the product’s directions and keep your sunscreen routine in place.</p></div></section>
<section class="image-story wrap"><div><img src="assets/images/aureveil-mist-campaign.webp" srcset="assets/images/aureveil-mist-campaign-480.webp 480w, assets/images/aureveil-mist-campaign.webp 960w" sizes="(max-width: 650px) calc(100vw - 40px), 45vw" alt="Aureveil Cloud Mist on ivory stone beside blue glass" width="960" height="1200" loading="lazy" decoding="async"><span class="image-caption">A LITTLE HYDRATION. A LIGHTER MOMENT.</span></div><div class="story-panel">${eyebrow('The mist, explained')}<h2>A dewy finish.<br><em>Without the guesswork.</em></h2><p>Think of Cloud Mist as a hydration step while getting ready, or a light refresh during your day. It is not intended to fix makeup or extend wear.</p><p>It carries no SPF rating and does not replace sunscreen or sunscreen reapplication.</p><a class="text-link" href="journal.html#hydration">Read our hydration guide ${arrow}</a></div></section>
<section class="section wrap narrow">${eyebrow('Simple things to know')}<h2>A closer look at <em>your mist.</em></h2>${faqs([['How do I use Cloud Mist?','Hold 20–30cm from the face and spray once or twice, then allow it to absorb. Follow the current packaging instructions.'],['Is Cloud Mist a makeup setting spray?','Cloud Mist is for hydration, refreshing and a dewy finish. It is not a makeup-fixing spray and does not promise longer makeup wear.'],['Does it provide sun protection?','No SPF is stated for Cloud Mist. Use a labelled sunscreen for sun protection and follow its reapplication directions.'],['Can I pair it with Daily Sun Serum?','Yes. Our Protect + Refresh Duo pairs Daily Sun Serum 50ml with Cloud Mist 120ml for daily protection and hydration. Explore both essentials on the <a href="duo.html">duo page</a>.']])}</section>${duoPreview()}`},
{file:'duo.html',nav:'shop',title:'Protect + Refresh Duo | Daily Sun Serum & Cloud Mist | Aureveil',description:'Discover the Aureveil Protect + Refresh Duo: Daily Sun Serum 50ml and Cloud Mist 120ml. Two complementary essentials for protection and hydration.',content:()=>`${crumbs('Protect + Refresh Duo')}
<section class="duo-hero wrap"><div class="duo-art"><div class="duo-circle"></div>${img('aureveil-sun-serum','Aureveil Daily Sun Serum','duo-sun',true)}${img('aureveil-cloudy-mist','Aureveil Cloud Mist','duo-mist')}<span class="seal">THE DAILY<br><i>duo</i></span></div><div class="duo-copy">${eyebrow('Two essentials. One thoughtful ritual.')}<h1>Protect your glow.<br><em>Refresh your day.</em></h1><p>Your daily SPF, plus a fine cloud of hydration. A simple pairing for long commutes, air-conditioned offices and everything in between.</p><div class="bundle-price"><span>S$84.90</span><div><small>Duo price</small><p>Save S$14.90 against individual prices</p></div></div><div class="duo-includes"><span>${svg('sun')}Daily Sun Serum · 50ml</span><span>${svg('drop')}Cloud Mist · 120ml</span></div><button class="btn btn-primary" data-open-duo>Explore the duo on Shopee ${external}</button></div></section>
<section class="section wrap"><div class="section-heading"><div>${eyebrow('Your two-step edit')}<h2>Different roles.<br><em>A considered pairing.</em></h2></div><p>Hydration and sun protection do different jobs.<br>Choose the essentials that fit your day.</p></div><div class="comparison-wrap"><table class="comparison"><caption class="sr-only">Comparison of the two products in the duo</caption><thead><tr><th scope="col">Your daily edit</th><th scope="col">Daily Sun Serum</th><th scope="col">Cloud Mist</th></tr></thead><tbody><tr><th scope="row">Main role</th><td>Daily UVA/UVB protection</td><td>Hydration and refreshing</td></tr><tr><th scope="row">Texture</th><td>Lightweight serum-like cream</td><td>Ultra-fine facial mist</td></tr><tr><th scope="row">Sun protection</th><td>SPF50+ PA++++</td><td>No SPF stated</td></tr><tr><th scope="row">Size</th><td>50ml</td><td>120ml</td></tr><tr><th scope="row">Individual price</th><td>S$39.90</td><td>S$59.90</td></tr></tbody></table></div></section>
<section class="section wrap split-copy subtle-top"><div>${eyebrow('A pairing, with purpose')}<h2>A ritual you can<br><em>make your own.</em></h2></div><div><p>This pairing brings together two complementary roles. Layering the products does not provide extra labelled UV protection. The Daily Sun Serum supplies the labelled SPF; the mist supplies hydration.</p><p>Start with your preferred skincare, finish with sunscreen according to the label, and use makeup afterwards if you choose. A mist is not a substitute for sunscreen reapplication.</p>${btn('routine.html','Personalise your ritual','btn btn-outline')}</div></section>
<section class="section wrap narrow"><h2>Before you <em>explore the duo.</em></h2>${faqs([['What is included in the duo?','Daily Sun Serum SPF50+ PA++++ 50ml and Cloud Mist 120ml. Together, they bring daily sun protection and refreshing hydration to your routine.'],['How do I shop the duo?','Select Explore the duo on Shopee to view the two product links, then choose Daily Sun Serum or Cloud Mist. Each link opens its product listing in a new tab.'],['Can I purchase one product?','Yes. Both products have their own pages and direct Shopee links. The Daily Sun Serum remains our main product; Cloud Mist is an optional supporting essential.']])}</section>`},
{file:'ingredients.html',nav:'ingredients',title:'Ingredients & Texture | Centella and Hyaluronic Acid | Aureveil',description:'Explore Aureveil’s ingredient guide to Centella, hyaluronic acid, green tea water and UV filters. Understand hydration and daily sun protection.',content:()=>`
<header class="page-heading wrap">${eyebrow('Care starts with understanding')}<h1>Thoughtful ingredients.<br><em>Beautifully explained.</em></h1><p>No ingredient buzzword needs to become another thing to worry about. Here is a clear introduction to ingredient roles in everyday skincare.</p></header>
<section class="ingredient-feature wrap"><div class="ingredient-visual">${img('aureveil-sun-detail','Aureveil Daily Sun Serum detail','',true)}</div><div>${eyebrow('The shared thread')}<h2>Centella meets<br><em>hydration.</em></h2><p>Centella asiatica and hyaluronic acid are familiar ingredients in moisturizing skincare. They offer different roles in a simple hydration routine.</p><p>Ingredient presence alone does not tell us how a finished product will feel on every person. Texture, the full formula and your individual skin all matter.</p></div></section>
<section class="section wrap ingredient-list"><article><span class="ingredient-number">01</span><div><p class="micro">IN BOTH PRODUCTS</p><h2>Centella asiatica</h2><p>A botanical ingredient commonly used in soothing, moisturizing skincare. An ingredient story is a guide to its role, rather than a promise of wrinkle reversal.</p></div>${svg('leaf')}</article><article><span class="ingredient-number">02</span><div><p class="micro">IN BOTH PRODUCTS</p><h2>Hyaluronic acid</h2><p>A humectant ingredient used to support hydration. It helps attract water and supports a comfortable, moisturized feel.</p></div>${svg('drop')}</article><article><span class="ingredient-number">03</span><div><p class="micro">IN THE CLOUD MIST</p><h2>Green tea water &amp; xylitol</h2><p>Green tea water is used in moisturizing skincare, while xylitol can contribute to a refreshing feel. Hydration ingredients do not provide an SPF rating.</p></div>${svg('star')}</article><article><span class="ingredient-number">04</span><div><p class="micro">IN THE DAILY SUN SERUM</p><h2>UV filters</h2><p>UV filters are the sunscreen ingredients that protect against ultraviolet radiation. Follow the finished product’s labelled SPF rating and directions; ingredient names alone cannot tell you its protection level.</p></div>${svg('sun')}</article></section>
<section class="section wrap narrow"><h2>The label is <em>your reference.</em></h2><p>Formulas can vary by market and change over time. Read the ingredient list on the item you buy, especially if you avoid a particular ingredient. Check the current product details and packaging on Shopee before purchasing.</p><div class="inline-actions">${btn('sun-serum.html','Explore the Daily Sun Serum')}${btn('cloudy-mist.html','Explore the mist','btn btn-outline')}</div></section>`},
{file:'routine.html',nav:'routine',title:'Find Your Daily Skincare Ritual | Private Routine Finder | Aureveil',description:'Find a simple Aureveil skincare ritual for workdays, makeup mornings or dry-feeling skin. Our browser-only routine finder requires no email or account.',content:()=>`
<header class="page-heading wrap">${eyebrow('Your day. Your daily edit.')}<h1>A little care.<br><em>Made to fit you.</em></h1><p>Tell us a little about your day. We will suggest how our two essentials could fit into it. Your answers stay in this page and are not stored or sent.</p></header>
<section class="quiz-section wrap"><aside class="quiz-aside"><span class="large-spark">✧</span><h2>Less guesswork.<br><em>More you.</em></h2><p>This is a simple product guide, not a diagnosis or personalised medical advice.</p><a class="text-link" href="privacy.html">How your privacy is protected ${arrow}</a></aside><form id="routine-form" class="routine-form"><fieldset><legend><span>01</span>What feels most relevant today?</legend><div class="choice-grid"><label class="choice"><input type="radio" name="priority" value="protection" required><span><strong>Daily protection</strong><small>I want to make SPF a habit.</small></span></label><label class="choice"><input type="radio" name="priority" value="hydration" required><span><strong>A hydration reset</strong><small>My skin can feel dry at work.</small></span></label><label class="choice"><input type="radio" name="priority" value="both" required><span><strong>A simple full routine</strong><small>I am interested in both.</small></span></label></div></fieldset><fieldset><legend><span>02</span>What does your morning usually look like?</legend><div class="choice-grid"><label class="choice"><input type="radio" name="morning" value="quick" required><span><strong>Out the door</strong><small>Keep the routine straightforward.</small></span></label><label class="choice"><input type="radio" name="morning" value="makeup" required><span><strong>A little makeup</strong><small>I make time to get ready.</small></span></label></div></fieldset><fieldset><legend><span>03</span>How do you like to start?</legend><div class="choice-grid"><label class="choice"><input type="radio" name="edit" value="single" required><span><strong>One essential</strong><small>Keep my edit focused.</small></span></label><label class="choice"><input type="radio" name="edit" value="duo" required><span><strong>A complementary duo</strong><small>Discover the complete pairing.</small></span></label></div></fieldset><button class="btn btn-primary" type="submit">Find my daily ritual ${arrow}</button><p class="fine-print">No name, email, skin photographs or health history requested. <a href="privacy.html">Read the privacy notice.</a></p></form><div id="routine-result" class="routine-result" hidden tabindex="-1" aria-live="polite"></div></section>
<noscript><div class="wrap notice">The personalised finder needs JavaScript. You can still <a href="sun-serum.html">explore the Daily Sun Serum</a>, <a href="cloudy-mist.html">view the mist</a> or <a href="duo.html">compare the duo</a>.</div></noscript>`},
{file:'journal.html',nav:'journal',title:'The Aureveil Journal | Sun Protection, Hydration & Daily Rituals',description:'Read original Aureveil guides to daily sunscreen, hydration at work and making skincare fit busy working days. Clear advice with links to primary sources.',content:()=>`
<header class="page-heading wrap">${eyebrow('The Aureveil journal')}<h1>A little knowledge.<br><em>A gentler routine.</em></h1><p>Original guides for full lives and thoughtful daily care. Clear information, without turning your skin into a project.</p></header>
<nav class="journal-nav wrap" aria-label="Journal articles"><a href="#sun-protection">Daily SPF</a><a href="#hydration">Hydration at work</a><a href="#your-pace">Care at your own pace</a></nav>
<article class="journal-article wrap" id="sun-protection"><div class="article-heading"><div><p class="micro">01 · THE EVERYDAY ESSENTIAL · 3 MIN READ</p><h2>Why your daily SPF deserves<br><em>a permanent place.</em></h2></div>${img('aureveil-sun-detail','Aureveil Daily Sun Serum for the daily SPF guide','',true)}</div><div class="article-body"><p class="lead">A useful skincare routine begins with things you can repeat.</p><p>Daily life in Singapore can include a commute, a walk for lunch and a little time outdoors between plans. Sun protection is worth considering as part of that ordinary day, rather than saving it for the beach.</p><h3>Protection is a long-term habit.</h3><p>A randomized trial followed 903 adults and found less progression of visible skin ageing with daily sunscreen use over 4.5 years, compared with discretionary use. That supports a prevention story; it does not establish that a sunscreen reverses age or extends lifespan.</p><h3>Choose a texture you will use.</h3><p>The Aureveil daily edit begins with Daily Sun Serum: lightweight hydration, SPF50+ PA++++ protection and a dewy finish. Your own preference matters: the point is a routine you can maintain while following the label.</p><h3>Give SPF its own step.</h3><p>Use sunscreen as the last step of basic skincare, following its packaging directions. Do not mix it into other products. Keep up label-directed reapplication and use shade and protective clothing too.</p><p class="source-note">Sources: <a href="https://pubmed.ncbi.nlm.nih.gov/23732711/" target="_blank" rel="noopener noreferrer">Hughes et al., sunscreen and skin ageing randomized trial</a>.</p>${btn('sun-serum.html','Discover the daily essential')}</div></article>
<article class="journal-article wrap" id="hydration"><div class="article-heading"><div><p class="micro">02 · THE LITTLE RESET · 2 MIN READ</p><h2>Hydration for the space<br><em>between meetings.</em></h2></div>${img('aureveil-mist-detail','Cloud Mist editorial photo for the hydration guide')}</div><div class="article-body"><p class="lead">Sometimes a routine needs a little breathing room.</p><p>If your skin feels dry during a long day, a moisturizing mist can be an optional moment of care. Cloud Mist is a fine facial spray for a refreshing feel and a dewy finish.</p><h3>Hydration, with a clear role.</h3><p>We suggest exploring the mist as part of your hydration routine before finishing skincare, or for a refreshing moment according to its directions. It is a complement to SPF, not a source of sun protection.</p><h3>Prep is different from fixing.</h3><p>A hydrated, dewy feel may be what you want while getting ready. Cloud Mist is a hydration step; it is not a makeup-fixing spray and does not promise longer makeup wear.</p>${btn('cloudy-mist.html','Meet the little reset')}</div></article>
<article class="journal-article wrap" id="your-pace"><div class="article-heading"><div><p class="micro">03 · A MORE CONSIDERED RITUAL · 3 MIN READ</p><h2>Your next chapter.<br><em>Your own pace.</em></h2></div><img src="assets/images/lifestyle.webp" alt="Portrait of a woman in her thirties in soft morning light" width="1536" height="1024" loading="lazy" decoding="async"></div><div class="article-body"><p class="lead">There is no deadline for having a perfect routine.</p><p>A few years into working life, you may start paying more attention to how your skin feels and looks. A busier calendar can make an elaborate ritual feel unrealistic. Our approach is to begin with a small edit and understand what each item does.</p><h3>Let each product earn its place.</h3><p>The Daily Sun Serum is our daily essential for labelled UV protection. The mist is optional support for hydration. Choose one, or explore the pair if both roles matter to you.</p><h3>Care does not have to mean correction.</h3><p>Aureveil’s editorial approach is about making room for comfortable, consistent care. Expression lines and changing skin do not make you a problem to solve. We do not promise that these products erase the effects of stress, reverse ageing or extend life.</p>${btn('routine.html','Find your own daily ritual')}</div></article>`},
{file:'about.html',nav:'about',title:'Our Story | Thoughtful Skincare for Full Lives | Aureveil',description:'Discover the story behind Aureveil: one woman’s corporate experience, a wish for a calmer morning ritual, and thoughtful daily skincare for full lives.',content:()=>`
<header class="page-heading wrap">${eyebrow('The Aureveil approach')}<h1>Care that makes room<br><em>for your life.</em></h1><p>A considered skincare edit for the person behind the busy calendar.</p></header>
<section class="editorial wrap"><div class="editorial-image"><img src="assets/images/lifestyle.webp" alt="Aureveil campaign portrait in calm, natural morning light" width="1536" height="1024" fetchpriority="high" decoding="async"></div><div class="editorial-copy">${eyebrow('Our founder’s story')}<h2>Full days.<br><em>Thoughtful essentials.</em></h2><p>Aureveil began with one woman who knew how easily work could take over. A few years into corporate life, long days, late nights and the pressure to keep up had become familiar. In her late twenties, she started noticing tired-looking skin and the first fine lines.</p><p>She hoped to keep her youthful glow, but an elaborate skincare routine felt like another task. She was looking for a comfortable sunscreen she would enjoy wearing, and a quiet moment each morning that belonged to her.</p><p>That wish became Aureveil. As a solo founder, she built the brand around simple daily care: sun protection for the day ahead and a refreshing mist for a small pause between meetings.</p><p>For working adults in their late twenties and early thirties, Aureveil is an invitation to make a little room for yourself. A moment of calm in the routine, and care you can return to every day.</p></div></section>
<section class="section wrap values"><article><span>01</span><h2>Clarity over noise.</h2><p>We explain the purpose of each product and make room for thoughtful choices. Ingredient stories should help you understand, not create more uncertainty.</p></article><article><span>02</span><h2>Care, without pressure.</h2><p>Our language welcomes the skin you have. We avoid promises of age reversal, perfect skin or longer life from buying skincare.</p></article><article><span>03</span><h2>A considered edit.</h2><p>We lead with one sunscreen and one optional supporting mist. You can discover each separately, or explore our duo.</p></article></section>
<section class="section wrap narrow subtle-top"><h2>A little clarity.<br><em>At every step.</em></h2><p>Aureveil brings a considered approach to daily sun protection and hydration. Purchases take place through external Shopee listings, with orders and payments handled there.</p></section>${routineCTA()}`},
{file:'faq.html',nav:'faq',title:'Frequently Asked Questions | Products, Prices & Shopee | Aureveil',description:'Find answers about Aureveil Daily Sun Serum, Cloud Mist, duo pricing, Shopee purchase links and the private routine finder.',content:()=>`
<header class="page-heading wrap">${eyebrow('A little clarity')}<h1>Good questions.<br><em>Thoughtful answers.</em></h1><p>From choosing your daily essential to finding your next step.</p></header>
<section class="section wrap faq-layout"><nav class="faq-nav" aria-label="FAQ categories"><a href="#products">The products</a><a href="#shopping">Prices &amp; shopping</a><a href="#privacy">Privacy &amp; Aureveil</a></nav><div><section id="products"><p class="eyebrow">The products</p>${faqs([['What is the main product in the Aureveil edit?','Aureveil Daily Sun Serum SPF50+ PA++++ 50ml. Cloud Mist 120ml is our optional supporting hydration product.'],['Does the mist replace sunscreen?','No. Cloud Mist is a hydrating facial mist with no stated SPF. Use labelled sun protection and follow its directions.'],['Can I call Cloud Mist a makeup setting spray?','Aureveil does not. Cloud Mist supports hydration, a refreshing feel and a dewy finish. It is not a makeup-fixing spray and does not promise longer wear.'],['Will these products reverse ageing?','We make no age-reversal or lifespan-extension claims. Our focus is daily sun protection, hydration and comfortable skincare.'],['Where can I check ingredients?','Visit our <a href="ingredients.html">ingredients guide</a> for an introduction to common ingredient roles. Always read the packaging on the product you receive for the current formula and directions.']])}</section><section id="shopping"><p class="eyebrow">Prices &amp; shopping</p>${faqs([['How do I shop Aureveil?','Choose your essential from The daily edit, then follow its Shopee link. Purchases are completed on Shopee.'],['What are the prices of the daily essentials?','Daily Sun Serum is S$39.90, Cloud Mist is S$59.90 and the Protect + Refresh Duo is S$84.90. The duo saves S$14.90 against the S$99.80 individual total.'],['What is included in the Protect + Refresh Duo?','The duo brings together Daily Sun Serum SPF50+ PA++++ 50ml and Cloud Mist 120ml. Visit the <a href="duo.html">duo page</a> to explore both products and their Shopee links.'],['Where can I get help with delivery or returns?','Use the seller chat or order support options on Shopee for delivery updates, returns and existing orders.']])}</section><section id="privacy"><p class="eyebrow">Privacy &amp; Aureveil</p>${faqs([['Do I need an account or email for the routine finder?','No. It asks only about preferences. Answers are processed in the current browser page, not stored or transmitted by Aureveil.'],['Does this website collect personal data?','Aureveil has no analytics, advertising trackers, newsletter signup or form backend. The hosting provider and external sites may process technical information under their own policies. See our <a href="privacy.html">privacy notice</a>.'],['Where are payments handled?','Purchases and payments are completed on Shopee. For help with an existing order, use the support options in your Shopee account.']])}</section></div></section>${routineCTA()}`},
{file:'contact.html',nav:'contact',title:'Help & Buying Guidance | Contact Options | Aureveil',description:'Get clear next steps for product questions and Shopee orders. Find Aureveil’s routine guide, product information and seller support links.',content:()=>`
<header class="page-heading wrap">${eyebrow('A little help, when you need it')}<h1>Let’s make the next<br><em>step a little clearer.</em></h1><p>Choose the kind of help you need. No account or personal details required.</p></header>
<section class="section wrap help-grid"><article>${svg('sun')}<p class="micro">CHOOSING YOUR DAILY EDIT</p><h2>Start with your ritual.</h2><p>Explore which product roles fit your day, then compare the essentials at your own pace.</p>${btn('routine.html','Find my daily ritual','btn btn-outline')}</article><article>${svg('drop')}<p class="micro">PRODUCT DETAILS</p><h2>Get to know the formulas.</h2><p>Understand the different roles of Daily Sun Serum and Cloud Mist, with a clear introduction to daily skincare ingredients.</p>${btn('ingredients.html','Read the ingredient guide','btn btn-outline')}</article><article>${svg('star')}<p class="micro">BUYING &amp; EXISTING ORDERS</p><h2>Speak to the seller.</h2><p>For stock, delivery, returns or order support, use the seller chat or support options available on the actual Shopee listing.</p>${link(sunURL,'Open the Shopee seller listing','btn btn-outline')}</article></section>
<section class="section wrap narrow subtle-top"><h2>Clear answers.<br><em>A thoughtful next step.</em></h2><p>For purchases and existing orders, contact the seller through Shopee. Order details, payments and delivery support are handled there.</p><p>For a closer look at your skincare options, explore the <a href="routine.html">routine finder</a> or <a href="ingredients.html">ingredient guide</a>. Read our <a href="privacy.html">privacy notice</a> for information about using this site.</p><a class="text-link" href="faq.html">Browse all frequently asked questions ${arrow}</a></section>`},
{file:'privacy.html',nav:'privacy',title:'Privacy Notice | Browser-Only Routine Finder | Aureveil',description:'Read how Aureveil handles privacy: no accounts, email signup, analytics or stored quiz answers. Understand external Shopee links and hosting-provider processing.',content:()=>`
<header class="page-heading wrap">${eyebrow('Clear by design')}<h1>Your routine.<br><em>Your privacy.</em></h1><p>Privacy notice for the Aureveil website. Updated 22 October 2026.</p></header>
<section class="section wrap prose"><h2>Who we are</h2><p>Aureveil is a skincare brand focused on daily protection and hydration. Purchases take place through external Shopee listings; orders and payments are handled there.</p><h2>Routine finder</h2><p>The form asks only about product and routine preferences. It requests no name, email, phone number, age, skin photograph or medical history. JavaScript processes selections within the current page. Answers are not sent to a server, saved to browser storage or used for profiling. Reloading or resetting the page clears the results.</p><h2>Cookies and tracking</h2><p>We do not set cookies, use localStorage, run analytics or embed advertising pixels. Fonts, images and scripts are served locally from this site. We do not embed third-party videos or social widgets.</p><h2>Hosting information</h2><p>If published on GitHub Pages, GitHub may log technical information including visitor IP addresses for security purposes. This is separate from Aureveil’s browser-only form. See <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages" target="_blank" rel="noopener noreferrer">GitHub Pages data collection information</a> and <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noopener noreferrer">GitHub’s Privacy Statement</a>.</p><h2>External websites</h2><p>Purchase buttons open existing Shopee product listings. We do not send routine-finder selections with those links. Shopee, its sellers and other external websites handle information under their own policies. Any purchasing or account interaction happens on those external sites.</p><h2>PDPA approach</h2><p>Our approach is to minimise data use: the site has no personal-data collection form or backend, and its routine finder does not persist answers. If we introduce email capture or analytics, we will update this privacy notice and explain the collection, consent, retention and access process.</p><h2>Using the site</h2><p>Do not enter personal or sensitive information in the routine finder. It is designed for general product preferences only. For order support, use the seller’s contact options on the relevant Shopee listing. This notice applies to the current Aureveil website.</p></section>`},
{file:'accessibility.html',nav:'accessibility',title:'Site Map & Browsing Help | Aureveil',description:'Find every Aureveil page in one place, from Daily Sun Serum and Cloud Mist to skincare guides, FAQs and simple tips for more comfortable browsing.',content:()=>`
<header class="page-heading wrap">${eyebrow('Find your way')}<h1>Explore Aureveil.<br><em>At your own pace.</em></h1><p>Your guide to our daily essentials, skincare journal and helpful answers.</p></header><section class="section wrap prose"><h2>Site map</h2><ul class="site-map"><li><a href="index.html">Home</a></li><li><a href="sun-serum.html">Daily Sun Serum</a></li><li><a href="cloudy-mist.html">Cloud Mist</a></li><li><a href="duo.html">Protect + Refresh Duo</a></li><li><a href="ingredients.html">Ingredients guide</a></li><li><a href="routine.html">Daily routine finder</a></li><li><a href="journal.html">The Aureveil journal</a></li><li><a href="about.html">Our story</a></li><li><a href="faq.html">Frequently asked questions</a></li><li><a href="contact.html">Help and contact options</a></li><li><a href="privacy.html">Privacy notice</a></li></ul><h2>Browse your way</h2><p>Make text larger with your browser’s zoom controls. You can also use the Tab key to move between links and buttons, and Enter to select.</p><p>Prefer less animation? Turn on Reduce Motion in your device settings.</p></section>`}
];

function header(active){ return `<a class="skip-link" href="#main">Skip to main content</a><div class="announcement"><div class="wrap"><p>Enjoy <strong>10% off</strong> your first purchase.</p></div></div><header class="site-header"><div class="wrap header-inner"><a class="brand" href="index.html">aureveil<span>THE DAILY SKIN EDIT</span></a><button class="menu-toggle" aria-controls="main-nav" aria-expanded="false" aria-label="Open navigation"><span></span><span></span></button><nav id="main-nav" class="main-nav" aria-label="Main navigation"><div class="shop-menu"><button class="nav-shop ${active==='shop'?'current':''}" aria-expanded="false" aria-controls="shop-links">The daily edit <span aria-hidden="true">⌄</span></button><div id="shop-links" class="shop-links" hidden><a href="sun-serum.html">Daily Sun Serum <small>The daily essential</small></a><a href="cloudy-mist.html">Cloud Mist <small>The little reset</small></a><a href="duo.html">Protect + Refresh Duo <small>The considered pairing</small></a></div></div><a href="ingredients.html" ${active==='ingredients'?'aria-current="page"':''}>Ingredients</a><a href="journal.html" ${active==='journal'?'aria-current="page"':''}>Journal</a><a href="about.html" ${active==='about'?'aria-current="page"':''}>Our story</a><a href="routine.html" class="nav-cta" ${active==='routine'?'aria-current="page"':''}>Find your ritual ${arrow}</a></nav></div></header>`; }
function footer(){return `<footer class="site-footer"><div class="wrap footer-main"><div class="footer-brand"><a class="brand" href="index.html">aureveil<span>THE DAILY SKIN EDIT</span></a><p>Care for today.<br><em>Glow into tomorrow.</em></p></div><div><h2>Discover</h2><a href="sun-serum.html">Daily Sun Serum</a><a href="cloudy-mist.html">Cloud Mist</a><a href="duo.html">Protect + Refresh Duo</a><a href="routine.html">Find your ritual</a></div><div><h2>A little clarity</h2><a href="ingredients.html">Ingredients</a><a href="journal.html">Journal</a><a href="faq.html">FAQs</a><a href="contact.html">Help &amp; contact</a></div><div><h2>Our approach</h2><a href="about.html">Our story</a><a href="privacy.html">Privacy notice</a><a href="accessibility.html">Site map</a></div></div><div class="wrap footer-disclaimer"><p>Purchases and order support are handled on Shopee.</p><div class="footer-bottom"><span>© 2026 Aureveil</span></div></div></footer>`;}
function modal(){return `<dialog id="duo-dialog" aria-labelledby="duo-dialog-title"><div class="dialog-head"><p class="eyebrow">Your daily pairing</p><button class="dialog-close" aria-label="Close product links">×</button></div><h2 id="duo-dialog-title">Explore the duo<br><em>on Shopee.</em></h2><p>Two daily essentials. Explore Daily Sun Serum and Cloud Mist on Shopee.</p><div class="dialog-products"><div>${img('aureveil-sun-serum','Daily Sun Serum packshot')}<div><h3>Daily Sun Serum</h3><p>50ml · SPF50+ PA++++</p>${link(sunURL,'View Daily Sun Serum','text-link')}</div></div><div>${img('aureveil-cloudy-mist','Cloud Mist packshot')}<div><h3>Cloud Mist</h3><p>120ml · Hydrating facial mist</p>${link(mistURL,'View Cloud Mist','text-link')}</div></div></div><p class="fine-print">Each product link opens Shopee in a new tab.</p></dialog>`;}

for(const page of pages){
  const html = `<!doctype html>\n<html lang="en-SG"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${page.title}</title><meta name="description" content="${page.description}"><meta name="theme-color" content="#f8f7f3"><meta name="color-scheme" content="light"><meta property="og:type" content="website"><meta property="og:title" content="${page.title}"><meta property="og:description" content="${page.description}">${base?`<link rel="canonical" href="${base+page.file}"><meta property="og:url" content="${base+page.file}"><meta property="og:image" content="${base}assets/images/aureveil-sun-campaign.webp">`:''}<link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><link rel="preload" href="assets/fonts/cormorant-garamond.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="assets/fonts/manrope.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="assets/site.css"><link rel="stylesheet" href="assets/luxury.css"><script src="assets/site.js" defer></script></head><body data-page="${page.nav}">${header(page.nav)}<main id="main">${page.content()}</main>${footer()}${modal()}</body></html>`;
  await writeFile(path.join(root,page.file),html,'utf8');
}
await writeFile(path.join(root,'.nojekyll'),'');
await writeFile(path.join(root,'robots.txt'),'User-agent: *\nAllow: /\n'+(base?`Sitemap: ${base}sitemap.xml\n`:''));
if(base){ await writeFile(path.join(root,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${pages.map(p=>`<url><loc>${base+p.file}</loc></url>`).join('')}</urlset>`); }
await mkdir(path.join(root,'reports'),{recursive:true});
console.log(`Built ${pages.length} pages (${pages.filter(p=>!['privacy.html','accessibility.html'].includes(p.file)).length} main pages), assets unchanged. ${base?'Canonical base: '+base:'Set SITE_URL before deployment to generate canonical links and sitemap.xml.'}`);
